let __v_251 = pyrt::literals::decode("{\"$tuple\":[\"threat\",\"threats\",\"threaten\",\"threatens\",\"threatened\",\"threatening\",\"violence\",\"violent\",\"attack\",\"attacked\",\"attacking\",\"assault\",\"assaulted\",\"punch\",\"punched\",\"hit\",\"hits\",\"hurt\",\"hurts\",\"kill\",\"killed\",\"stab\",\"stabbed\",\"knife\",\"weapon\",\"grabbed\",\"grabs\",\"shoved\",\"shoves\",\"kicked\",\"kicks\"]}")?;
